function connectionMethodArea(connection,row){
 const methods=connection.methods||[];if(!methods.length)return;
 row.querySelector('[data-connection-methods]')?.remove();const area=document.createElement('section');area.dataset.connectionMethods=connection.id;
 const selected=current.connectionSelection?.connection===connection.id?current.connectionSelection.method:current.connection===connection.id?current.connectionMethod:null;
 area.innerHTML='<h3>연결 방식</h3><p class="small">방식 선택은 설정 초안만 저장합니다. 계정 확인과 실제 전송은 별도 검토합니다.</p>';
 for(const method of methods){const item=document.createElement('article');item.className='field';item.dataset.connectionMethod=method.id;item.innerHTML='<strong>'+esc(method.title)+'</strong><p>'+esc(method.summary)+'</p><p class="small" data-method-status>'+esc(method.status)+'</p>';
 const choose=document.createElement('button');choose.type='button';choose.dataset.operation='connection-method';choose.dataset.methodChoice=method.id;choose.textContent=selected===method.id?'이 방식 선택됨':'이 방식 선택';choose.setAttribute('aria-pressed',String(selected===method.id));choose.dataset.supported=String(current.aiState!=='running');choose.onclick=()=>work(async()=>{await view.call('chooseConnectionMethod',{connection:connection.id,method:method.id});connectionMethodArea(connection,row);},'연결 방식 설정 초안 저장됨 · 호출 없음');item.append(choose);
 const detail=document.createElement('div');detail.dataset.methodDetails=method.id;detail.hidden=selected!==method.id;detail.innerHTML='<p>설정 항목: '+esc((method.fields||[]).join(', '))+'</p><ol>'+(method.steps||[]).map(step=>'<li>'+esc(step)+'</li>').join('')+'</ol>';
 const settings=document.createElement('button');settings.type='button';settings.dataset.operation='connection-settings';settings.dataset.methodSettings=method.id;settings.textContent='이 방식의 설정 편집';settings.onclick=()=>editConnectionSettings(connection.id);
 const bind=document.createElement('button');bind.type='button';bind.dataset.operation='connection';bind.dataset.methodBind=method.id;bind.textContent='저장한 설정으로 연결 선택';bind.dataset.supported=String(current.aiState!=='running');bind.onclick=()=>work(()=>view.call('bindConnection',{connection:connection.id}),'연결 설정 선택됨 · 계정 인증과 실제 호출은 별도 검토');detail.append(settings,bind);
 if(/^https:\/\//.test(method.documentation||'')){const link=document.createElement('a');link.href=method.documentation;link.target='_blank';link.rel='noopener noreferrer';link.textContent='공식 연결 안내';detail.append(link);}
 item.append(detail);area.append(item);
 }
 row.append(area);controls();
}

function showConnections(preferred=null){
 const w=openWindow('connections','AI 연결 팩 · 선택과 설정',500,400);
 w.body.innerHTML='<div class="window-content"><p>설정 선택과 실제 호출 승인은 별개입니다. 메시지는 기존 전송 전 검토에서 별도로 승인합니다.</p><div id="connection-list"></div></div>';
 for(const connection of current.connections||[]){
  const row=document.createElement('div');row.className='field';row.dataset.connectionRow=connection.id;
  const status=document.createElement('p');status.className='small';status.dataset.connectionStatus='';status.textContent=connectionStatus(connection);row.append(status);
  if(!connection.runtimeSupported){const reason=document.createElement('p');reason.className='small';reason.textContent=connection.capabilities?.unsupportedReason||'현재 호스트의 실행 지원이 확인되지 않았습니다.';row.append(reason);}
  const select=document.createElement('button');select.dataset.operation='connection';select.textContent=connection.id;select.onclick=()=>(connection.methods||[]).length?connectionMethodArea(connection,row):work(()=>view.call('bindConnection',{connection:connection.id}),'연결 팩이 로컬에 선택됨 · 전송 없음');
  const settings=document.createElement('button');settings.dataset.operation='connection-settings';settings.dataset.connectionSettings=connection.id;settings.textContent='설정 편집';settings.title='현재 프로젝트를 숨기고 기존 팩 설정 편집을 엽니다. 작업은 원래 프로젝트에 유지됩니다.';settings.onclick=()=>editConnectionSettings(connection.id);
  row.append(select,settings);$('#connection-list',w.body).append(row);if((connection.methods||[]).length&&(preferred===connection.id||current.connectionSelection?.connection===connection.id||current.connection===connection.id))connectionMethodArea(connection,row);
 }
 controls();
}

function closeActiveProject(){
 const scope=current.projectId;if(!scope)return;
 const active=current.aiState==='running'||(current.workers||[]).some(row=>['running','dispatching'].includes(row.status))||['building','running'].includes(current.executionState);
 const close=()=>work(async()=>{if(current.projectId!==scope)throw Error('종료 대상 프로젝트가 바뀌었습니다.');await actualWorkspace.flush();await view.call('closeProject',{confirmed:true});},'프로젝트 완전 종료 · 초안 유지');
 if(!active){close();return;}
 modal('작업 중인 프로젝트 종료',`<p>이 프로젝트의 실행 중인 AI·Worker 또는 프로젝트 실행을 종료하고 완전히 닫을까요?</p><p>계속 작업을 선택하면 현재 작업이 유지됩니다.</p><div class="actions"><button data-keep-project>계속 작업</button><button class="danger" data-confirm-project-close>작업 종료 후 닫기</button></div>`,(root,dismiss)=>{$('[data-keep-project]',root).onclick=dismiss;$('[data-confirm-project-close]',root).onclick=()=>{dismiss();close();};});
}
function showChat(){const scope=current.projectId,body=$('#chat-inner');body.hidden=false;$('#execution-logs').hidden=true;$('#chat').classList.add('selected');$('#logs-tab').classList.remove('selected');if($('#chat-input'))return;body.innerHTML=`<div class="messages" id="messages"><div class="message"><strong id="chat-helper">${esc(current.aiHelperId||current.helperProfile?.helper||'')}</strong><span id="chat-output">${esc(current.aiOutput||'')}</span></div></div><form class="chat-compose" id="chat-form"><textarea id="chat-input" maxlength="4096" aria-label="프로젝트 채팅 입력" placeholder="함께 만들 내용을 남겨보세요…">${esc(conversations.get(scope)??current.chatDraft??'')}</textarea><button class="primary" data-operation id="chat-prepare" type="submit" aria-label="메시지 보내기">보내기</button></form>`;
$('#chat-input').oninput=()=>conversations.set(scope,$('#chat-input').value);
$('#chat-input').onblur=e=>{if($('#chat-form').contains(e.relatedTarget)||e.relatedTarget?.closest('.brand')||current.projectId!==scope||busy)return;const value=$('#chat-input')?.value;if(value!==undefined&&value!==current.chatDraft)work(()=>view.call('chatDraft',{value}),'프로젝트 대화 초안 저장됨 · 전송 없음');};
$('#chat-form').onsubmit=e=>{e.preventDefault();work(async()=>{const value=$('#chat-input').value;await view.call('chatDraft',{value});await view.call('prepareAI',{kind:'chat',message:value});showPreview();},'전송 전 검토 준비됨 · 전송 없음');};controls();}

function showPreview(){
 const preview=current.aiPreview;if(!preview)return;const w=openWindow('ai-preview','AI 전송 전 검토',640,500),token=preview.token;if($('.augment-overlay')){$('#workspace').append(w.el);workspaceRuntime.focusWindow(w);}
 w.body.innerHTML=`<div class="window-content"><p>${esc(preview.connection)} · ${esc(preview.kind)} · ${esc(preview.target||'')}</p><pre class="consumer-output">${esc(preview.message)}</pre><p>${esc(preview.rights)}</p>${preview.nodeAssignment?'<details open data-node-approval><summary>이번 전송의 노드 정의와 범위</summary><pre class="consumer-output">'+esc(JSON.stringify(preview.nodeAssignment,null,2))+'</pre><p>도구는 이 노드만 읽고 수정합니다. Helper 기억은 이번 노드 요청에 보내지 않습니다.</p></details>':'<details><summary>이번 전송의 Helper 범위와 기억</summary><pre class="consumer-output">'+esc(JSON.stringify(preview.helperContext,null,2))+'</pre></details>'}<details><summary>모델·호출 제한</summary><pre class="consumer-output">${esc(JSON.stringify({pins:preview.pins,limits:preview.limits},null,2))}</pre></details>${preview.diagnostics?.checks?.length?'<details open data-connection-diagnostics><summary>연결 진단</summary>'+preview.diagnostics.checks.map(check=>'<p>'+esc(check.label)+': '+esc(check.status)+'</p>').join('')+'</details>':''}<p>${esc((preview.disclosures||[]).join(' '))}</p><div id="permission-choices"></div><p>${preview.canStart?'':esc(preview.blockedReason||'이 대상에서 실행 지원이 확인되지 않았습니다.')}</p><button data-operation id="ai-start" data-token="${esc(token)}" data-supported="false">승인한 내용으로 시작</button><button data-operation id="cancel-preview">검토 취소</button></div>`;
 for(const requirement of preview.requirements||[]){const label=document.createElement('label'),input=document.createElement('input');input.type='checkbox';input.dataset.permission=requirement.id;input.dataset.operation='permission-choice';input.checked=preview.approvals?.[requirement.id]===true;input.onchange=()=>work(async()=>{await view.call('permission',{token,id:requirement.id,approved:input.checked});previewControls();},'이번 전송 권한 선택됨 · 아직 전송 없음');label.append(input,document.createTextNode(requirement.label||requirement.id));$('#permission-choices').append(label);}
 $('#ai-start').onclick=()=>work(async()=>{if(current.aiPreview?.token!==token)throw Error('전송 검토가 변경되었습니다. 다시 검토하세요.');await view.call('startAI',{token});closeWindow('ai-preview');},preview.kind==='adoption-record'?'로컬 채택 기록 확인됨 · 전송 없음':'승인된 AI 요청 시작됨 · 최종 소스 반영은 별도 검토');$('#cancel-preview').onclick=()=>work(async()=>{await view.call('cancelPreview',{});closeWindow('ai-preview');},'검토 취소됨 · 전송 없음');previewControls();controls();updateHelperPresentations();
}
function previewControls(){const button=$('#ai-start'),preview=current?.aiPreview;if(!button)return;button.dataset.supported=String(button.dataset.token===preview?.token&&preview?.canStart===true&&(preview.requirements||[]).every(r=>preview.approvals?.[r.id]===true));button.disabled=busy||button.dataset.supported==='false';}
function showAugment(refresh=false){const space=$('#workspace');if(!space)return;let w=windows.get('augment');if(!w){const el=document.createElement('section');el.className='augment-overlay';el.setAttribute('role','dialog');el.setAttribute('aria-label','증강 선택');space.append(el);w={key:'augment',el,body:el,meta:{},overlay:true};windows.set('augment',w);}w.meta.snapshot=JSON.stringify(current.augment);const batch=current.augment,cards=batch?.cards||[],custom=batch?.customCards||[],scope=current.projectId;w.body.innerHTML=`<div class="augment-panel"><header class="augment-heading"><h2>${esc(batch?.reason||'어떤 방향으로 프로젝트를 확장할까요?')}</h2></header><div class="augment-grid">${cards.length?cards.map((card,i)=>`<article class="augment-card" data-grade="${esc(card.rarity)}" style="--card-order:${i}"><small class="augment-grade">${esc(card.rarity||'')}</small><h3>${esc(card.title||card.coreIdea||card.idea||card.id)}</h3><p>${esc(card.summary||'')}</p><div class="tags">${(card.tags||[]).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><small>${esc(card.effort||'')} ${esc(card.risk||'')}</small><button class="primary" data-operation data-card="${esc(card.id)}" data-supported="${card.eligibility==='current'&&batch?.canCustom===true}">이 방향 선택</button></article>`).join(''):'<p class="augment-empty">아직 생성된 증강이 없어요.</p>'}</div>${batch?.localBlocked?`<p class="editor-note" data-local-proposal-blocked>${esc(batch.localBlocked)}</p>`:''}<section data-custom-proposals><h3>내가 쓴 제안 · ${batch?.customCount||0}</h3>${(batch?.customCount||0)>32?`<div class="actions"><button data-operation data-custom-page="${(batch?.customPage||0)-1}" data-supported="${(batch?.customPage||0)>0}">더 최근 제안</button><small>${(batch?.customPage||0)+1} / ${Math.max(1,Math.ceil((batch?.customCount||0)/32))} 페이지 · 최신 묶음부터</small><button data-operation data-custom-page="${(batch?.customPage||0)+1}" data-supported="${((batch?.customPage||0)+1)*32<(batch?.customCount||0)}">이전 제안</button></div>`:''}${custom.map(card=>`<article class="augment-card"><h4>${esc(card.summary)}</h4><small>범위: ${(card.targets||[]).map(esc).join(', ')} · ${esc(card.eligibility)}</small><div class="actions"><button data-operation data-card="${esc(card.id)}" data-supported="${card.eligibility==='current'&&batch?.canCustom===true}">작업으로 선택</button><button data-operation data-custom-discard="${esc(card.id)}">보관하기</button></div></article>`).join('')}</section><footer class="augment-footer"><button class="secondary augment-reroll" data-operation id="reroll">↻ 리롤</button><div class="augment-footer-actions"><button data-close>취소</button><button data-defer>보류하기</button><button data-operation data-custom-propose data-supported="${batch?.canCustom===true}">내 제안</button><button data-operation data-propose>Helper에 제안 요청</button><button data-operation data-skip-proposals data-supported="${!!batch?.batch&&batch?.canCustom===true&&batch?.state!=='running'}">현재 생성 제안 비우기</button></div></footer></div>`;
const prepare=()=>work(async()=>{if(current.projectId!==scope)throw Error('프로젝트 범위가 바뀌었습니다.');await view.call('prepareAI',{kind:'proposals',target:current.draft?.id,message:directions.get(scope)||''});showPreview();},'증강 방향 검토 준비됨 · 호출 없음');$('#reroll').onclick=()=>modal('증강 리롤 검토',`<p>새 실제 제안 생성은 기존 전송 전 검토와 별도 승인이 필요합니다. 횟수 제한이나 자동 다음 제안은 설정하지 않습니다.</p><button data-review-proposals class="primary">새 제안 요청 검토</button>`,(r,close)=>{$('[data-review-proposals]',r).onclick=()=>{close();prepare();};});$('[data-defer]',w.body).onclick=()=>closeWindow('augment');const dismiss=$('[data-close]',w.body);dismiss.textContent='닫기 · 제안 유지';dismiss.title='현재 제안과 작업을 보존하고 창을 닫습니다.';dismiss.onclick=()=>closeWindow('augment');$('[data-propose]',w.body).onclick=()=>modal('증강 제안하기',`<form class="stack"><label for="augment-direction">어떤 변화를 제안하고 싶나요?</label><textarea id="augment-direction" rows="4" maxlength="2048" required>${esc(directions.get(scope)||'')}</textarea><button class="primary" type="submit">제안하기</button></form>`,(r,close)=>{$('#augment-direction',r).oninput=e=>{directions.set(scope,e.target.value);actualWorkspace.schedule();};$('form',r).onsubmit=e=>{e.preventDefault();directions.set(scope,$('#augment-direction',r).value);close();prepare();};});$('[data-custom-propose]',w.body).onclick=()=>modal('내 증강 제안',`<form class="stack"><p>범위: ${esc(batch?.targets?.[0]||current.draft?.id||'선언을 선택하세요.')}</p><label>제안 내용<textarea data-custom-text rows="4" maxlength="2048" required></textarea></label><p>이 컴퓨터의 제안 이력에 저장합니다. 작업으로 선택하면 준비 상태의 Worker가 생깁니다.</p><button data-operation class="primary" type="submit">제안 저장</button></form>`,(r,close)=>{$('form',r).onsubmit=e=>{e.preventDefault();const text=$('[data-custom-text]',r).value,commandID=crypto.randomUUID(),target=batch?.targets?.[0]||current.draft?.id;work(async()=>{if(current.projectId!==scope)throw Error('프로젝트 범위가 바뀌었습니다.');await view.call('customProposal',{target,commandID,text});close();showAugment();},'내 제안 저장됨 · 전송 없음');};});
 $('[data-skip-proposals]',w.body).onclick=()=>modal('현재 생성 제안 비우기',`<p>보고 있는 생성 제안 묶음을 비우고 이력을 보존합니다. 선택한 작업과 직접 쓴 제안은 유지됩니다.</p><button data-operation data-confirm-skip>현재 묶음 비우기</button>`,(r,close)=>{$('[data-confirm-skip]',r).onclick=()=>work(async()=>{if(current.projectId!==scope)throw Error('프로젝트 범위가 바뀌었습니다.');await view.call('skipProposals',{commandID:crypto.randomUUID(),batch:batch.batch,text:'Explicitly cleared current generated proposals'});close();showAugment();},'현재 제안 묶음 비움 · 이력 유지');});
 for(const button of $$('[data-custom-page]',w.body))button.onclick=()=>work(async()=>{if(current.projectId!==scope)throw Error('프로젝트 범위가 바뀌었습니다.');await view.call('customProposalPage',{page:Number(button.dataset.customPage)});showAugment();},'보존된 내 제안 목록 · 전송 없음');
 for(const button of $$('[data-custom-discard]',w.body))button.onclick=()=>work(async()=>{if(current.projectId!==scope)throw Error('프로젝트 범위가 바뀌었습니다.');await view.call('discardCustom',{commandID:crypto.randomUUID(),card:button.dataset.customDiscard});showAugment();},'내 제안 보관됨 · 선택한 작업 유지');
 $$('[data-card]',w.body).forEach(b=>b.onclick=()=>work(async()=>{await view.call('selectCard',{card:b.dataset.card});showAugment();},'Worker 작업 선택됨'));w.el.onkeydown=e=>{if(e.key==='Escape'){e.stopPropagation();closeWindow('augment');}};controls();}
const workerEvidence=new Map(),workerSourceSelections=new Map();
function restoreWorkerPanel(id){const w=openWindow('worker','Worker 기록 조회',580,480,{refresh:true,meta:{workerId:id}});w.body.innerHTML='<div class="window-content">실제 프로젝트 Worker 기록을 조회하고 있습니다. 승인과 실행은 재생하지 않습니다.</div>';if(!panelInspection){const scope=current.projectId;panelInspection=(async()=>{while(busy||actualWorkspace.loading)await new Promise(resolve=>setTimeout(resolve,50));if(current.projectId!==scope)return;await work(()=>view.call('inspectPanels',{}),'실제 Worker 기록 조회 · 실행 없음');if(current.projectId!==scope)return;const worker=(current.workers||[]).find(row=>row.id===id);if(worker){showWorker(worker,true);}else{w.body.innerHTML='<div class="window-content">이 실제 Worker ID의 현재 기록을 확인할 수 없습니다. 자동 생성·실행하지 않습니다.</div>';}})().finally(()=>panelInspection=null);}return w;}
function showWorker(worker,refresh=false){
 const scope=current.projectId,key=scope+'|'+worker.id,w=openWindow('worker','Worker 상태 · '+worker.id,580,480,{refresh});w.meta.workerId=worker.id;w.meta.snapshot=JSON.stringify([worker,current.aiOwnerAvailable,current.planningOwnerAvailable,current.connection,current.augment?.canCustom]);const checked=workerSourceSelections.get(key)||new Set();
 w.body.innerHTML=`<div class="window-content"><h2>${esc(worker.id)}</h2><p>${esc(worker.ownerHelper||'')} · ● ${esc(worker.status)}${worker.assignedNode?' · '+esc(worker.assignedNode):''} · 채택 기록 ${esc(worker.adoptionState||'none')}</p><pre class="consumer-output">${esc(JSON.stringify({kind:worker.taskKind,assignedNode:worker.assignedNode,goal:worker.goal,stage:worker.stage,completion:worker.completion,progress:worker.progress,blocker:worker.blocker},null,2))}</pre><div class="actions"><button data-operation id="worker-prepare">작업 전 검토</button><button data-operation id="worker-cancel-ready" data-supported="${worker.status==='ready'&&current.planningOwnerAvailable&&current.augment?.canCustom===true}">준비 작업 취소</button><button data-operation id="worker-stop">작업 중지</button><button data-operation id="worker-recover">새 복구 작업 검토</button><button data-operation id="worker-adoption-record">채택 기록 검토</button></div><h3>이 Worker의 기록된 미반영 변경</h3><div id="worker-source-list"></div><button data-operation id="worker-review">선택한 변경 Review</button><p>초안과 진행 상태는 유지됩니다. Source Confirm과 작업 채택·완료 기록은 구분합니다. Worker 개별 채팅은 제공하지 않습니다.</p></div>`;
 for(const id of [...(worker.changedIds||[]),...(worker.supportingDraftIds||[]).filter(id=>!(worker.changedIds||[]).includes(id))]){const label=document.createElement('label'),input=document.createElement('input');input.type='checkbox';input.dataset.workerSource=id;input.checked=checked.has(id);input.onchange=()=>{const selected=workerSourceSelections.get(key)||new Set();input.checked?selected.add(id):selected.delete(id);workerSourceSelections.set(key,selected);};label.append(input,document.createTextNode(id+((worker.supportingDraftIds||[]).includes(id)?' · 함께 검토할 사용자 변경':'')));$('#worker-source-list').append(label);}
 const run=async(endpoint)=>{if(current.projectId!==scope)throw Error('Worker project changed');await view.call(endpoint,{task:worker.id});};
 $('#worker-cancel-ready').onclick=()=>work(async()=>{if(current.projectId!==scope)throw Error('Worker project changed');await view.call('cancelReadyWorker',{task:worker.id,commandID:crypto.randomUUID(),reason:'Explicitly cancelled before execution'});},'준비 작업 취소됨 · 실행/원본 변경 없음');
 $('#worker-prepare').onclick=()=>work(async()=>{await run('prepareWorker');showPreview();},'Worker 전송 전 검토');$('#worker-stop').onclick=()=>work(()=>run('stopWorker'),'Worker 중지 요청됨 · 초안 유지');
 $('#worker-recover').textContent=worker.assignedNode?'현재 노드로 새 Task 검토':'새 복구 작업 검토';$('#worker-recover').onclick=()=>worker.assignedNode?nodeTasksUI.open(0,worker.assignedNode):work(async()=>{await run('recoverWorker');showPreview();},'별도 복구 작업 검토 · 자동 재실행 없음');$('#worker-adoption-record').onclick=()=>work(async()=>{await run('inspectAdoption');showPreview();},'로컬 채택 기록 검토 · 전송 없음');
 $('#worker-review').onclick=()=>work(async()=>{if(dirty||[...schemaInputs.keys(),...blueprintInputs.keys()].some(key=>key.startsWith(scope+'|')))throw Error('미적용 입력을 먼저 적용하세요. 입력은 유지됩니다.');const ids=$$('[data-worker-source]:checked').map(input=>input.dataset.workerSource);if(!ids.length)throw Error('검토할 실제 변경을 선택하세요');await view.call('reviewWorker',{task:worker.id,ids,target:targetChoices.get(current.projectId)||current.runTarget});showWorkerReview(worker);},'Worker 변경 검토 · 아직 최종 반영 없음');if(!current.aiOwnerAvailable){const local=current.planningOwnerAvailable;w.body.insertAdjacentHTML('afterbegin',local?'<p class="editor-note">로컬 제안으로 준비한 작업입니다. 연결한 AI로 작업 전 검토를 열면 모델과 내용을 확인한 뒤 별도로 전송을 승인할 수 있습니다.</p>':'<p class="editor-note">저널의 실제 상태입니다. 실행 소유자가 복원되지 않아 승인·실행·채택 동작은 사용할 수 없습니다. 자동 재실행하지 않습니다.</p>');for(const b of $$('#worker-prepare,#worker-stop,#worker-recover,#worker-adoption-record,#worker-review',w.body)){b.dataset.supported='false';b.disabled=true;}if(local&&worker.status==='ready'&&current.augment?.canCustom===true)$('#worker-cancel-ready',w.body).dataset.supported='true';if(local&&current.connection&&worker.status==='ready'){$('#worker-prepare',w.body).dataset.supported='true';$('#worker-prepare',w.body).textContent='연결한 AI로 작업 전 검토';}}if(worker.assignedNode&&current.planningOwnerAvailable){$('#worker-recover',w.body).dataset.supported='true';}controls();
}
function showWorkerReview(worker){
 const review=current.review;if(!review)return;const scope=current.projectId,key=scope+'|'+worker.id,token=review.token,ids=review.units.map(unit=>unit.id),w=openWindow('worker-review','Worker 변경 채택 검토',680,510);
 w.body.innerHTML=`<div class="window-content"><h2>${esc(worker.goal||worker.id)}</h2><p>${esc(review.status)} · ${ids.length}개 소스 · 채택은 기존 컴파일 검증과 기록 계약을 따릅니다.</p>${worker.assignedNode?'<p>Worker 범위: '+esc(worker.assignedNode)+'. 함께 선택한 graph·계약 변경은 사용자가 별도로 검토하며 이 Worker의 작성으로 기록하지 않습니다.</p>':''}${review.units.map(unit=>`<details><summary>${esc(unit.id)} · 고급 변경 보기</summary><label>Before</label><pre class="consumer-output">${esc(unit.before)}</pre><label>After</label><pre class="consumer-output">${esc(unit.after)}</pre></details>`).join('')}<label>실제로 확인한 작업 결과와 남은 실행 검증</label><textarea id="worker-goal-evidence" maxlength="4096">${esc(workerEvidence.get(key)||'')}</textarea><button data-operation id="worker-adopt" data-supported="${review.status==='ready'}">검토한 변경 Confirm 및 작업 채택 기록</button><p>Source Confirm만으로 목표 달성이나 실행 검증이 만들어지지 않습니다. 확인한 근거를 명시하세요.</p></div>`;
 $('#worker-goal-evidence').oninput=()=>workerEvidence.set(key,$('#worker-goal-evidence').value);$('#worker-adopt').onclick=()=>work(async()=>{if(current.projectId!==scope||current.review?.token!==token||current.selectedWorkerId!==worker.id||dirty||[...schemaInputs.keys(),...blueprintInputs.keys()].some(key=>key.startsWith(scope+'|')))throw Error('선택·검토·입력이 바뀌었습니다. 입력을 적용하고 다시 검토하세요.');await view.call('adoptWorker',{task:worker.id,token,ids,goalEvidence:$('#worker-goal-evidence').value});workerEvidence.delete(key);closeWindow('worker-review');},'검토한 소스 채택 및 기존 완료 기록 검증됨 · 실행 제한은 명시한 근거대로 유지');controls();
}


